syntax:
switch (valor)
{
    case x:
        ...
        break;
    default:
        ...
        break;
}

example:
string rune = "fire";
string door;
switch (rune)
{
    case "fire":
        door = "left";
        break;
    case "ice":
        door = "right";
        break;
    default:
        door = "back";
        break;
}
